style.css:
@-moz-document domain("roblox.com") {
:root {
    --angel-wallpaper: url("https://i.pinimg.com/736x/fd/35/47/fd3547664b8f4b66a5c4515d6149589f.jpg");
  }

  /* full-screen Roblox wallpaper */
  html,
  body {
    background-color: #f8d9ec !important;
    background-image: var(--angel-wallpaper) !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    min-height: 100vh !important;
  }

  /* transparent page containers */
  #wrap,
  #container-main {
    background-color: transparent !important;
  }

  /* pink links */
  a {
    color: #c58ba9 !important;
  }
}
